(function(){var r;function u(){var t=window.AAArt||{},i=window.AARoutes||{},m=t.ART,p=t.LEAD,a=t.H3,f=t.artNote,R=t.artLink,x=t.artInsightLink,E=t.DeadlinesRoadmap,k=t.SBRRoadmap,T=t.FiveCornerDiagram,D=t.EInvoiceCTA,C=t.EInvoiceGuideLinks,y=i.pathForPage,g=i.pathForInsight,O=i.INSIGHTS;function w({onNav:l}){const s=(e,o)=>React.createElement("a",{href:y(e),onClick:c=>{c.preventDefault(),l(e)},style:{color:"var(--aa-cyan-text)",fontWeight:600,textDecoration:"none"}},o),n=(e,o)=>React.createElement("a",{href:g(e),onClick:c=>{c.preventDefault(),l("insight",e)},style:{color:"var(--aa-cyan-text)",fontWeight:600,textDecoration:"none"}},o),b=[{k:"(1) Required by labour law",covers:"Benefits that labour legislation in the State or any free zone, financial free zones included, makes mandatory.",now:"Accommodation is excluded, unless a MoHRE decision or directive makes providing it mandatory."},{k:"(2) Contract or documented policy",covers:"Benefits provided under a contractual obligation or a documented policy.",now:"In the cases, and on the conditions, set by FTA Decision No. 17 of 2026: six cases, every condition met."},{k:"(3) Health insurance",covers:"Health insurance, enhanced cover included, for employees and family up to one spouse and three children under eighteen.",now:"Unchanged."},{k:"(4) Deemed supplies",covers:"Goods or services whose provision is a deemed supply under the Decree-Law, on which the employer accounts for output tax (Article 11 of the Decree-Law).",now:"Unchanged."}],A=[{k:"Transport",art:"Art. 2(1)",c:["Only between home and the workplace or clients\u2019 premises, or for other purposes directly related to the job.","Not used for the employee\u2019s personal benefit.","The employee cannot opt for a cash allowance or other financial compensation instead."]},{k:"Food and drink",art:"Art. 2(2)",c:["The employee lives in a remote, distant or isolated area.","No appropriate facilities for preparing food at the employee\u2019s residence or workplace, as the case may be, and no nearby restaurants or outlets where food and drink can easily be obtained.","Directly linked to the work or residence period the job requires.","No option of a cash allowance instead."]},{k:"Accommodation",art:"Art. 2(3)",c:["No option of a cash allowance or financial compensation instead.","Related to the operational requirements of the work, and not part of the employee\u2019s benefits or ordinary compensation.","The work requires the employee to live near the workplace, the site or the client.","For the employee alone, with no family or other personal use \u2014 unless the employee must live permanently near the workplace so that it is their usual residence.","Commensurate with the job and basic residency needs, with no significant recreational or personal elements."]},{k:"New employees\u2019 housing",art:"Art. 2(4)",c:["Temporary, for no longer than 30 days.","Commensurate with the job and basic residency needs."]},{k:"Phones and internet",art:"Art. 2(5)",c:["Mobile phones, airtime, data packages and home internet are necessary for the job, including outside normal hours or away from the workplace.","Used for work, with any personal use incidental and insignificant.","A documented internal policy sets out the permitted use and the consequences of unauthorised use.","Reasonable monitoring of use and of compliance with the policy, with records kept where there is unauthorised use."]},{k:"Parking",art:"Art. 2(6)",c:["Parking fees for spaces allocated to employees, incurred solely for business purposes, directly related to the employee\u2019s duties or to business visits and related assignments.","A documented internal policy on when parking is reimbursed and how it is approved.","Documents proving payment kept, such as receipts showing the date, time, amount and the tax paid."]}],h={padding:"16px 0",borderBottom:"1px solid var(--aa-rule)"},d={display:"flex",flexWrap:"wrap",alignItems:"baseline",gap:"4px 12px",fontSize:17,margin:0},v={fontSize:12,color:"var(--aa-steel-700)",letterSpacing:"0.04em"};return React.createElement("div",{className:"container",style:m},React.createElement("p",{style:p},"FTA Decision No.\xA017 of 2026 was issued on ",React.createElement("strong",null,"9\xA0September")," and took effect on ",React.createElement("strong",null,"1\xA0October\xA02026"),", the same day as the amended Article\xA053 of the VAT Executive Regulation. From that day, the exception that keeps input VAT on benefits given to staff under a contract or documented policy recoverable applies only \u201Cin accordance with the cases and conditions specified by the Authority\u201D. This Decision is those cases. There are ",React.createElement("strong",null,"six"),": transport, food and drink for staff living in remote areas, accommodation, up to 30 days\u2019 housing for new employees, phones and home internet, and parking. Each comes with conditions, and ",React.createElement("strong",null,"all")," of them must be met. Three of the cases share a test worth checking first: the employee must not be able to take cash instead."),React.createElement("h3",{style:a},"Where the Decision sits"),React.createElement("p",null,"Article\xA053(1)(c) of the Executive Regulation blocks input tax on goods and services bought \u201Cto be used by employees for no charge to them and for their personal benefit including the provision of entertainment services\u201D. Four exceptions let it back in, and from 1\xA0October two of them read differently:"),React.createElement("div",{style:{marginTop:8,borderTop:"1px solid var(--aa-rule)"}},b.map(e=>React.createElement("div",{key:e.k,style:h},React.createElement("h4",{style:d},React.createElement("strong",null,e.k)),React.createElement("p",{style:{margin:"6px 0 0"}},e.covers),React.createElement("p",{style:{margin:"4px 0 0"}},React.createElement("strong",null,"From 1\xA0October\xA02026:")," ",e.now)))),React.createElement("p",{style:{marginTop:20}},"Before 1\xA0October route (2) carried its own test: the benefit had to be provided \u201Cin order that they may perform their role\u201D and be shown to be \u201Cnormal business practice\u201D. Cabinet Decision No.\xA0149 of 2026 removes that test and hands the question to the Authority, and Decision\xA017 answers it. The Decision applies only to route (2) (Art.\xA01). Our reading is that Article\xA02 is a closed list: a benefit that fits none of the six cases does not recover through route (2). It may still recover through another route. And the block reaches only what employees use free of charge for their personal benefit \u2014 which, Article\xA053(1)(c) says, includes entertainment services, defined in Article\xA053(2)(a) to include accommodation, and food and drink not provided in the normal course of a meeting."),React.createElement("h3",{style:a},"The six cases"),React.createElement("p",null,"Each case lists its conditions, and every one of them must be met."),React.createElement("div",{style:{marginTop:8,borderTop:"1px solid var(--aa-rule)"}},A.map(e=>React.createElement("div",{key:e.k,style:h},React.createElement("h4",{style:d},React.createElement("strong",null,e.k)," ",React.createElement("span",{className:"mono",style:v},e.art)),React.createElement("ul",{style:{margin:"8px 0 0",paddingLeft:20,display:"grid",gap:4}},e.c.map(o=>React.createElement("li",{key:o},o)))))),React.createElement("p",{style:{marginTop:16,fontSize:15,color:"var(--aa-steel-700)"}},"Article numbers are those of FTA Decision No.\xA017 of 2026. The English text is the Authority\u2019s unofficial translation; the Arabic governs."),React.createElement("p",null,"Two things sit outside the cases. Transport bought in as a passenger service \u2014 a contracted staff bus with its driver, a taxi \u2014 is usually exempt local passenger transport (Article\xA046(4) of the Decree-Law; Article\xA045 of the Executive Regulation), so there is often no input tax to recover. And a car or van for up to ten people, driver included, that is available for personal use stays blocked by Article\xA053(1)(b), which Decision\xA017 does not change."),React.createElement("h3",{style:a},"Accommodation: the two routes that matter"),React.createElement("p",null,React.createElement("strong",null,"First, check that there is VAT to recover.")," A lease of a residential building is exempt where it runs for more than six months or the tenant holds an Emirates ID (Article\xA046(2) of the Decree-Law; Article\xA043(1) of the Executive Regulation), so the rent on a flat or villa leased for staff usually carries no input tax at all. Hotels, hotel apartments and serviced apartments are not residential buildings (Article\xA037(2)), and their charges carry VAT. Whether a particular labour camp is a residential building is a question of fact under Article\xA037. The input tax this section is about is on those standard-rated stays, and on standard-rated costs around the housing \u2014 furnishing, maintenance, cleaning, utilities."),React.createElement("p",null,"Housing is where the Decision and the amended Regulation meet. From 1\xA0October, input tax on accommodation an employer provides free to staff comes back through one of two routes:"),React.createElement("ul",null,React.createElement("li",null,React.createElement("strong",null,"Mandatory under a MoHRE decision or directive.")," Route (1) keeps benefits that labour legislation makes mandatory, but now excludes accommodation unless a decision or directive of the Ministry of Human Resources and Emiratisation makes providing it mandatory. Where one does, the input tax recovers on that route, and Decision\xA017 does not apply to it."),React.createElement("li",null,React.createElement("strong",null,"Under a contract or policy, and meeting case 3")," \u2014 or case 4 where a new employee\u2019s temporary stay lasts no longer than 30 days \u2014 with every condition met.")),React.createElement("p",null,"The condition to think hardest about is Art.\xA02(3)(b). The accommodation must be \u201Crelated to the operational requirements of the work\u201D and must not \u201Cform part of the employee\u2019s benefits or ordinary compensation arrangements\u201D. Yet route (2) itself requires a contract or documented policy to provide it. On our reading, the two fit together where the contract or policy records the housing as a requirement of the work \u2014 a project site, a shift pattern, a remote location, a client\u2019s premises \u2014 and not as an item in the pay package; housing offered as part of the package, of the kind an employee might otherwise be paid an allowance for, will struggle with Art.\xA02(3)(b) however the contract is worded. And where the employee could take the allowance instead, Art.\xA02(3)(a) decides it."),React.createElement("p",null,"Two more conditions narrow it. The housing must be for the employee alone, with no family and no other personal use, unless the employee is required to live permanently near the workplace so that the accommodation is their usual residence (Art.\xA02(3)(d)). And it must be commensurate with the job and basic residency needs, without significant recreational or personal elements (Art.\xA02(3)(e)). On our reading, staff accommodation beside a project site is the case these words describe; family housing in the city, offered as part of the package, is not."),React.createElement("p",null,"New joiners have a separate, lighter case: temporary accommodation for ",React.createElement("strong",null,"no longer than 30 days"),", commensurate with the job and basic needs (Art.\xA02(4)). Keep the stay inside the 30 days. The condition is on the period of provision, and the text does not say what happens to the first 30 days of a longer stay."),React.createElement("h3",{style:a},"The cash-allowance test"),React.createElement("p",null,"Three of the six cases \u2014 transport, food and drink, accommodation \u2014 fail if the employee is able to take cash instead (Art.\xA02(1)(c), 2(2)(d) and 2(3)(a)). The test is about the ",React.createElement("em",null,"option"),", not the choice made. On our reading, an offer letter or HR policy that says \u201Caccommodation provided, or a housing allowance in lieu\u201D puts the input tax on that housing at risk for everyone the wording covers, including the employees who took the housing. It is the quickest of the tests to check, because the answer is in documents you already hold."),React.createElement("h3",{style:a},"Phones, internet and parking: the policy is the evidence"),React.createElement("p",null,"The last two cases are about paperwork as much as purpose. Phones, airtime, data and home internet meet case\xA05 only where a ",React.createElement("strong",null,"documented internal policy")," sets the permitted use and the consequences of misuse, and where the employer can show ",React.createElement("strong",null,"reasonable monitoring")," of use and compliance, with records where the policy was breached (Art.\xA02(5)(c) and (d)). Personal use has to be incidental and insignificant, not the main purpose. Parking needs a documented reimbursement policy with an approval mechanism, and the evidence of payment kept \u2014 the Decision\u2019s example is a receipt showing the date, time, amount and the tax paid (Art.\xA02(6)(b) and (c))."),React.createElement("p",null,"None of that is difficult. On our reading, all of it has to be in place, and working, for the period the claim covers: a policy written when the return falls due does not show how the phones were used in the months before it. The policy is also the first thing to have ready if the claim is ever questioned."),React.createElement("h3",{style:a},"Food and drink: remote residence only"),React.createElement("p",null,"This is the narrowest case. It needs a place of residence that is remote, distant or isolated, no appropriate facilities for preparing food at the residence or workplace, as the case may be, and nowhere nearby to obtain it easily, a direct link to the work or residence period the job requires, and no cash alternative (Art.\xA02(2)). It fits a camp at a remote site. On our reading, meals for staff in a city office \u2014 a catered lunch, a stocked pantry \u2014 do not meet the first two conditions, so they do not recover on this route."),React.createElement("h3",{style:a},"On the date"),React.createElement("p",null,"The Decision took effect on 1\xA0October\xA02026 (Art.\xA03), the day the amended Article\xA053 did. Neither instrument has a transitional rule for Article\xA053. Where one purchase spans the date \u2014 a year\u2019s serviced-apartment contract paid in advance, an annual phone contract \u2014 work out which part falls under which rule (on our reading, the date of supply of each part decides it) before the return that claims it, and write the reason down."),React.createElement("h3",{style:a},"What to do now"),React.createElement("ul",null,React.createElement("li",null,React.createElement("strong",null,"Pull every ledger that carries input VAT on staff costs")," \u2014 housing, transport, meals, phones and data, parking, and anything else employees receive free \u2014 and map each line either to one of the four routes or, where employees do not use it free of charge for their personal benefit, to \u2018outside the block\u2019, with the reason."),React.createElement("li",null,React.createElement("strong",null,"For housing"),", establish for each group of workers whether a MoHRE decision or directive makes it mandatory. Where none does, test case 3, or case 4 where a new joiner\u2019s stay lasts no more than 30 days, condition by condition, and record the operational reason in the contract or policy. Check first that the housing carries VAT at all."),React.createElement("li",null,React.createElement("strong",null,"Search offer letters and HR policies for a cash alternative")," to transport, meals or housing. Where the option exists, that benefit cannot meet case 1, 2 or 3 on the text; a new joiner\u2019s stay of no more than 30 days (case 4) has no cash condition."),React.createElement("li",null,React.createElement("strong",null,"Write or update two policies"),": phones and internet (permitted use, consequences, monitoring) and parking reimbursement (when, and who approves). Keep the parking receipts."),React.createElement("li",null,React.createElement("strong",null,"For supplies from 1 October"),", stop claiming input tax on benefits that fall within the block and fit no route \u2014 a quarterly return for August to October covers both rules \u2014 and tag those ledger codes so the claim does not come back by default.")),React.createElement("p",null,"Our ",s("service-vat-filing","VAT return filing")," work covers the input-tax review behind each return. ",n("vat-executive-regulation-amendments-october-2026","The Cabinet Decision 149 note")," has every other amendment that takes effect on 1\xA0October."),f("Written on 28 September 2026 from the Federal Tax Authority\u2019s published text of Decision No. 17 of 2026 on the Cases and Conditions for the Recovery of Input Tax Incurred on Employee Expenses (issued 9 September 2026, in force 1 October 2026), and Article 53 of Cabinet Decision No. 52 of 2017 as amended by Cabinet Decision No. 149 of 2026, read in the Ministry of Finance\u2019s consolidated text of September 2026. The earlier wording of Article 53(1)(c)(2) is from the Ministry\u2019s previous consolidated text of the Regulation. We had not seen an Authority guide or public clarification on the Decision at the date of writing. The English texts are unofficial translations; the Arabic governs. General information on published law, not advice on your own position."),React.createElement("div",{style:{marginTop:28,borderTop:"1px solid var(--aa-rule)",paddingTop:20}},React.createElement("div",{className:"eyebrow eyebrow--charcoal",style:{marginBottom:12}},"Related"),React.createElement("ul",{style:{margin:0,paddingLeft:0,listStyle:"none",display:"grid",gap:8,fontSize:15}},React.createElement("li",null,n("vat-executive-regulation-amendments-october-2026","Every VAT Regulation change from 1 October \u2192")),React.createElement("li",null,n("fta-decision-13-supplier-verification","Decision 13: supplier checks before you claim input VAT \u2192")),React.createElement("li",null,n("uae-tax-changes-october-2026","Every UAE tax and reporting date in October 2026 \u2192")),React.createElement("li",null,s("service-vat-filing","VAT return filing \u2192")),React.createElement("li",null,s("tool-vat","UAE VAT calculator \u2192")))))}return w}(window.AAArticleBodies=window.AAArticleBodies||{})["fta-decision-17-employee-benefits-input-vat"]=function(t){return r||(r=u()),r(t)}})();
